            southOpenings: [[-3.0, 3.0]], // Open slot for South Staircase down to Dry Floor (y = -12.0m)
            eastOpenings: [[-3.2, 3.2]],  // Open slot for West-to-Rotunda Bridge & Stairs
            westOpenings: [],
            supportToY: floorY,
            pillarCountX: 2,
