            const banner = new THREE.Mesh(new THREE.PlaneGeometry(3.4, 10.5), crimsonBannerMat);
            banner.rotation.y = Math.PI / 2;
            banner.position.set(-65.8, upperPadY + 8.5, tz);
            westBastionGroup.add(banner);
